Algorithm Triangulo
  Define a As Integer;
  Define b As Integer;
  Define c As Integer;
  Read a;
  Read b;
  Read c;
  If a >= b + c Or b >= a + c Or c >= a + b Then
    Write "no es triángulo";
  Else
    If a = b And b = c Then
      Write "equilátero";
    Else
      If a = b Or b = c Or a = c Then
        Write "isósceles";
      Else
        Write "escaleno";
      EndIf
    EndIf
  EndIf
EndAlgorithm
